#include <windows.h>
#include <iphlpapi.h>
#include <stdio.h>

#pragma comment(lib, "iphlpapi.lib")

int main() {
    ULONG size = 0;
    GetAdaptersInfo(nullptr, &size);
    auto buffer = static_cast<PIP_ADAPTER_INFO>(LocalAlloc(LPTR, size));
    if (buffer == nullptr) {
        return 1;
    }

    if (GetAdaptersInfo(buffer, &size) == ERROR_SUCCESS) {
        for (PIP_ADAPTER_INFO adapter = buffer; adapter != nullptr;
                adapter = adapter->Next) {
            printf("Adapter: %s\n", adapter->Description);
        }
    }

    LocalFree(buffer);
    return 0;
}

