#include <windows.h>
#include <iphlpapi.h>
#include <icmpapi.h>
#include <stdio.h>

#pragma comment(lib, "iphlpapi.lib")

int main() {
    HANDLE icmp = IcmpCreateFile();
    if (icmp == INVALID_HANDLE_VALUE) {
        return 1;
    }

    char request[] = "example";
    BYTE reply[sizeof(ICMP_ECHO_REPLY) + 32] = {};
    DWORD count = IcmpSendEcho(icmp, inet_addr("127.0.0.1"), request,
        sizeof(request), nullptr, reply, sizeof(reply), 1000);
    printf("Replies: %lu\n", count);

    IcmpCloseHandle(icmp);
    return 0;
}

