#include <windows.h>
#include <lm.h>
#include <stdio.h>

#pragma comment(lib, "netapi32.lib")

int main() {
    PSHARE_INFO_1 buffer = nullptr;
    DWORD entries = 0;
    DWORD total = 0;
    DWORD resume = 0;

    if (NetShareEnum(nullptr, 1, reinterpret_cast<LPBYTE*>(&buffer),
            MAX_PREFERRED_LENGTH, &entries, &total, &resume) == NERR_Success) {
        for (DWORD i = 0; i < entries; ++i) {
            printf("Share: %ls\n", buffer[i].shi1_netname);
        }
        NetApiBufferFree(buffer);
    }
    return 0;
}

