#include <windows.h>
#include <winnetwk.h>
#include <stdio.h>

#pragma comment(lib, "mpr.lib")

int main() {
    HANDLE enumeration = nullptr;
    DWORD result = WNetOpenEnumA(RESOURCE_CONTEXT, RESOURCETYPE_DISK,
        RESOURCEUSAGE_CONNECTABLE, nullptr, &enumeration);
    if (result != NO_ERROR) {
        return 1;
    }

    char buffer[4096] = {};
    DWORD count = 1;
    DWORD size = sizeof(buffer);
    result = WNetEnumResourceA(enumeration, &count, buffer, &size);
    if (result == NO_ERROR || result == ERROR_MORE_DATA) {
        printf("Enumerated %lu resource(s).\n", count);
    }

    WNetCloseEnum(enumeration);
    return 0;
}

